+import { createRef } from 'react';
+
+import { render } from '@testing-library/react';
+
+import Dialog from './Dialog';
+
+describe('Dialog', () => {
+    it('uses an accessible fallback host and forwards attributes, children, and ref without native dialog support', () => {
+        const ref = createRef<HTMLDialogElement>();
+        const { getByRole } = render(
+            <Dialog ref={ref} open aria-label="Example" data-testid="dialog-host" className="custom">
+                <button type="button">Hello</button>
+            </Dialog>
+        );
+
+        const host = getByRole('dialog', { name: 'Example' });
+        expect(host.tagName).toBe('DIV');
+        expect(host).toHaveAttribute('open');
+        expect(host).toHaveAttribute('data-testid', 'dialog-host');
+        expect(host).toHaveClass('custom');
+        expect(ref.current).toBe(host);
+        expect(getByRole('button', { name: 'Hello' })).toBeVisible();
+    });
+
+    it('uses a native dialog and forwards attributes and ref when supported', () => {
+        const originalShowModal = HTMLDialogElement.prototype.showModal;
+        HTMLDialogElement.prototype.showModal = jest.fn();
+        try {
+            const ref = createRef<HTMLDialogElement>();
+            const { getByRole } = render(
+                <Dialog ref={ref} open aria-label="Example" data-testid="dialog-host">
+                    <button type="button">Hello</button>
+                </Dialog>
+            );
+
+            const host = getByRole('dialog', { name: 'Example' });
+            expect(host.tagName).toBe('DIALOG');
+            expect(host).toHaveAttribute('open');
+            expect(host).toHaveAttribute('data-testid', 'dialog-host');
+            expect(ref.current).toBe(host);
+            expect(getByRole('button', { name: 'Hello' })).toBeVisible();
+        } finally {
+            if (originalShowModal) {
+                HTMLDialogElement.prototype.showModal = originalShowModal;
+            } else {
+                delete (HTMLDialogElement.prototype as { showModal?: typeof HTMLDialogElement.prototype.showModal })
+                    .showModal;
+            }
+        }
+    });
+});
